def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = opp.count('D')
    my_d = me.count('D')

    if opp_d == n:
        return 'D'

    c_to_d = 0
    c_to_c = 0
    d_to_d = 0
    d_to_c = 0
    for i in range(n - 1):
        if me[i] == 'C':
            if opp[i + 1] == 'D':
                c_to_d += 1
            else:
                c_to_c += 1
        else:
            if opp[i + 1] == 'D':
                d_to_d += 1
            else:
                d_to_c += 1
    p_d_after_c = c_to_d / (c_to_d + c_to_c) if (c_to_d + c_to_c) > 0 else 0.0
    p_d_after_d = d_to_d / (d_to_d + d_to_c) if (d_to_d + d_to_c) > 0 else 0.0
    p_c_after_d = 1.0 - p_d_after_d

    last_opp = opp[-1]
    last_me = me[-1]
    opp_rate = opp_d / n
    remaining = 100 - n

    if remaining <= 3:
        if opp_rate < 0.4 or p_c_after_d > 0.5:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if remaining <= 6 and opp_rate < 0.2:
        return 'D'

    if opp_d == 0:
        if my_d / n < 0.1:
            if n >= 5 and all(a == 'C' for a in me[-5:]):
                return 'D'
        return 'C'

    if p_c_after_d < 0.3 and opp_rate < 0.5:
        return 'C'

    if p_c_after_d > 0.6 and opp_rate < 0.4:
        if n > 10 and rng.random() < 0.6:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            if opp_rate < 0.3 and n > 10:
                return 'C'
            return 'D'
        else:
            return 'D'
    else:
        if last_me == 'D':
            return 'C'
        return 'C'
